def solve(data):
    left, right = data['base']
    if left >= right:
        return []
    pieces = [[left, right]]
    for a, b in data['blocked']:
        if a >= b:
            continue
        next_pieces = []
        for start, end in pieces:
            if b <= start or a >= end:
                next_pieces.append([start, end])
            else:
                if start < a:
                    next_pieces.append([start, a])
                if b < end:
                    next_pieces.append([b, end])
        pieces = next_pieces
    return [p for p in pieces if p[0] < p[1]]

